{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "useTableRowIndex",
    "subComponentOf": "Table",
    "displayName": "useTableRowIndex",
    "description": "Hook that returns a TablePlugin which prepends a right-aligned, monospaced row-number column, starting at 1 by default. Without data, Table supplies row positions; with data, ordinary numbers follow that array. Windowed rows use the parent Table logical position directly; nondefault startFrom values use full rendering.",
    "props": [
      {
        "name": "data",
        "type": "T[]",
        "description": "Optional: the array whose order the numbers follow. Omit it to number rows from the positions Table gives them."
      },
      {
        "name": "getRowKey",
        "type": "(item: T) => string",
        "description": "Optional key extractor used with data, returning a unique string per row. When provided, rows match data by the returned string; otherwise by reference identity. Memoize with useCallback for a stable plugin identity."
      },
      {
        "name": "label",
        "type": "ReactNode",
        "description": "Header label for the index column.",
        "default": "'#'"
      },
      {
        "name": "startFrom",
        "type": "number",
        "description": "First index value.",
        "default": "1"
      }
    ]
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
